    def findDuplicate(self, nums: List[int]) -> int:
        # Trying to use cycle detection idea
        slow = nums[0]
        fast = nums[nums[0]]
        while slow != fast:
            slow = nums[slow]
            fast = nums[nums[fast]]
        return slow"}
